public static int calculateTimeNeeded(int N) {
    if (N < 2) {
        throw new IllegalArgumentException("N must be at least 2");
    }

    int timeNeeded = 0;
    int leftIndex = 0;
    int rightIndex = 1;

    while (leftIndex < N && rightIndex < N) {
        timeNeeded++;
        int leftPerson = N - leftIndex;
        int rightPerson = N - rightIndex;

        if (leftPerson > rightPerson) {
            leftIndex++;
        } else if (leftPerson < rightPerson) {
            rightIndex++;
        } else {
            leftIndex++;
            rightIndex++;
        }
    }

    return timeNeeded;
}

