public static int calculateTimeNeeded(int N) {
    // Handle edge case where N is less than or equal to 2.
    if (N <= 2) {
        return 0;  // No need to swap if there are 2 or less people.
    }

    int timeNeeded = Integer.MAX_VALUE;
    for (int i = 1; i <= N - 1; i++) {
        // Calculate the number of swaps needed for a single pass.
        int swaps = (i - 1) * 2;
        timeNeeded = Math.min(timeNeeded, swaps * (N - i));
    }

    // For the last pass, calculate the number of swaps needed.
    timeNeeded += (N - 1) * 2;

    return timeNeeded;
}

