public List<List<Integer>> permute(int[] nums) {
        // Initialize the result list to hold the permutations
        List<List<Integer>> result = new ArrayList<>();
        // Helper function to rotate subarray from start_index to end_index
        rotate(nums, 0, nums.length - 1);
        return result;
    }

private void rotate(int[] nums, int start_index, int end_index) {
        while (start_index < end_index) {
            int temp = nums[start_index];
            nums[start_index] = nums[end_index];
            nums[end_index] = temp;
            start_index++;
            end_index--;
        }
    }

