private void helper(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            result.add(new ArrayList<>(Arrays.asList(nums))); // Without the .clone() method, List cats up second object
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, i, start);
            helper(nums, start + 1, result);
            swap(nums, i, start); // Backtracking
        }
    }

private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

public List<List<Integer>> permute(int[] nums) {
        if (nums == null || nums.length == 0) {
            return Arrays.asList(new ArrayList<>());
        }

