private void permuteRecursive(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            result.add(new ArrayList<>(Arrays.asList(nums)));
        } else {
            for (int i = start; i < nums.length; i++) {
                swap(nums, start, i);
                permuteRecursive(nums, start + 1, result);
                swap(nums, start, i); // backtrack
            }
        }
    }

private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

