private void permute(int[] nums, ArrayList<List<Integer>> list, ArrayList<Integer> temp) {
        if (temp.size() == nums.length) {
            list.add(new ArrayList<>(temp));
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (temp.contains(nums[i])) continue;
            temp.add(nums[i]);
            permute(nums, list, temp);
            temp.remove(temp.size() - 1);
        }
    }

public int findLargestSubstring(List<String> strings) {
    int maxCount = -1;
    Map<String, Integer> substringIndices = new HashMap<>();

    for (String string : strings) {
        Set<String> substrings = new HashSet<>();
        int len = string.length();
        for (int i = 0; i < len; i++) {
            substrings.add(string.substring(i));
            if (len - i > 0) {
                substrings.add(string.substring(i));
            }
        }
        for (String ss : substrings) {
            if (substringIndices.containsKey(ss)) {
                substringIndices.put(ss, substringIndices.get(ss) + 1);
            } else {
                substringIndices.put(ss, 1);
            }
            maxCount = Math.max(maxCount, substringIndices.get(ss));
        }
    }

    if (maxCount < 0) {
        return 0;
    }

    int largest = -1;
    for (Map.Entry<String, Integer> entry : substringIndices.entrySet()) {
        if (entry.getValue() == maxCount) {
            largest = Math.max(largest, entry.getKey().length());
        }
    }

    return largest;
}

