public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        throw new IllegalArgumentException("List of strings cannot be null or empty");
    }

    int maxLength = 0;

    for (String str : strings) {
        reverseString(str);
        for (String otherStr : strings) {
            if (otherStr.contains(str) || otherStr.contains(reverseStr)) {
                maxLength = Math.max(maxLength, str.length());
                reverseString(str); // Restore original string for next iteration
                break;
            }
        }
    }

    return maxLength;
}

private String reverseString(String str) {
    String reversed = "";
    for (int i = str.length() - 1; i >= 0; i--) {
        reversed += str.charAt(i);
    }
    return reversed;
}

public static int countOilDeposits(char[][] grid) {
    // Helper method to check if DFS can be performed
    private static boolean dfs(int i, int j, int N, int M, Set<String> visited, char[][] grid) {
        if (i < 0 || j < 0 || i >= N || j >= M || visited.contains(i + "," + j) || grid[i][j] != '@') {
            return false;
        }
        visited.add(i + "," + j);
        dfs(i + 1, j, N, M, visited, grid);
        dfs(i - 1, j, N, M, visited, grid);
        dfs(i, j + 1, N, M, visited, grid);
        dfs(i, j - 1, N, M, visited, grid);
        return true;
    }

    // Main method to count the number of oil deposits
    public static int countOilDeposits(char[][] grid) {
        int N = grid.length;
        int M = grid[0].length;
        int count = 0;
        Set<String> visited = new HashSet<>();

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (grid[i][j] == '@' && !visited.contains(i + "," + j)) {
                    count++;
                    dfs(i, j, N, M, visited, grid);
                }
            }
        }

        return count;
    }
}

