public static int maxRegions(int N) {
    // Check for invalid input
    if (N < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    // If N is 0 or 1, there are 0 or 1 region respectively
    if (N == 0 || N == 1) {
        return 0;
    }

    // If N is 2, there are 4 regions (0, 1, 2, 3)
    if (N == 2) {
        return 4;
    }

    // For N greater than 2, use the formula 3N(N-1)/2
    return (3 * N * (N - 1)) / 2;
}

