    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int next : graph.get(current)) {
            if (!visited[next]) {
                queue.add(next);
                visited[next] = true;
            }
        }
    }

    return "cannot be travelled";
}

