    }

    int commonCount = 0;
    int totalLength = word1.length() + word2.length();

    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) >= 0) {
            commonCount++;
        }
    }

    if (totalLength == 0) {
        return "appx("; // Special case when we're dividing by zero
    }

    int num = commonCount;
    int den = totalLength;

    while (num > den) {
        int temp = num % den;
        num = den;
        den = temp;
    }

