}

public static String appx(String word1, String word2) {
    // Initialize the count of common letters
    int commonCount = 0;

    // Convert both strings to character arrays to easily compare characters
    char[] charArray1 = word1.toCharArray();
    char[] charArray2 = word2.toCharArray();

    // Count the common letters
    for (char c : charArray1) {
        if (Arrays.stream(charArray2).anyMatch(x -> x == c)) {
            commonCount++;
        }
    }

    // Compute the approximate value
    BigInteger commonFactor = new BigInteger(String.valueOf(commonCount));
    BigInteger totalFactor = new BigInteger(String.valueOf(word1.length() + word2.length()));

    // Simplify the fraction by finding the greatest common divisor
    BigInteger gcd = commonFactor.gcd(totalFactor);
    commonFactor = commonFactor.divide(gcd);
    totalFactor = totalFactor.divide(gcd);

