    char[] chars1 = word1.toCharArray();
    char[] chars2 = word2.toCharArray();

    // Count common characters
    int commonCount = 0;
    for (int i = 0; i < chars1.length; i++) {
        for (int j = 0; j < chars2.length; j++) {
            if (chars1[i] == chars2[j]) {
                commonCount++;
                chars2[j] = '_'; // Mark as processed to avoid double counting
                break;
            }
        }
    }

    // Calculate the fraction
    if (commonCount == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0/1";
    }
    int numerator = commonCount;
    int denominator = chars1.length + chars2.length - commonCount;

    // Simplify the fraction
    while (denominator % numerator != 0) {
        int temp = denominator;
        denominator = numerator;
        numerator = temp % numerator;
    }

    // Return the simplified fraction
    return "appx(" + word1 + ", " + word2 + ") = " + commonCount + "/" + denominator;
}

