public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false; // Odd number of elements, not possible to form pairs
    }
    Map<Integer, Integer> modCount = new HashMap<>(); // Map to store the count of each remainder when divided by k
    for (int num : arr) {
        int remainder = num % k;
        if (remainder == 0) {
            modCount.put(0, modCount.getOrDefault(0, 0) + 1);
        } else {
            modCount.put(remainder, modCount.getOrDefault(remainder, 0) + 1);
            // Check if a complementary sum exists for the current remainder
            if (modCount.containsKey(k - remainder)) {
                int cnt1 = modCount.get(remainder);
                int cnt2 = modCount.get(k - remainder);
                modCount.put(remainder, cnt1 - 1);
                modCount.put(k - remainder, cnt2 - 1);
            } else {
                return false; // No complementary sum exists
            }
        }
    }
    return true;
}

