            continue;
        }

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false; // If the array has an odd number of elements, it's impossible to form pairs of equal sum.
    }

    Arrays.sort(arr);

    for (int i = 0; i < arr.length / 2; i++) {
        int currentSum = arr[i] + arr[arr.length - 1 - i];
        if (currentSum % k != 0) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    Map<Integer, Boolean> visited = new HashMap<>();
    return dfs(0, graph, hasApple, visited);
}

private int dfs(int node, List<List<Integer>> graph, boolean[] hasApple, Map<Integer, Boolean> visited) {
    visited.put(node, true);
    int time = 0;
    for (int neighbor : graph.get(node)) {
        if (!visited.get(neighbor)) {
            time += dfs(neighbor, graph, hasApple, visited);
        }
    }

    if (hasApple[node] || time > 0) time += 2;

    return time;
}

