    dfs(0, -1, 0, hasApple, graph, count);
    return minTime;
}

private int amount(int i, int parent, int depth, boolean[] hasApple, List<Integer>[] graph, int[] count) {
        int res = 0;
        for(int nxt : graph[i]) {
            if(nxt != parent) {
                res += (1 + count[nxt]);
            }
        }
        if(res > 1 || hasApple[i]) count[i] = res >= 1 ? 1 : 0;
        return res;
    }

private int dfs(int i, int parent, int depth, boolean[] hasApple, List<Integer>[] graph, int[] count) {
        int res = amount(i, parent, depth, hasApple, graph, count);

        for(int nxt : graph[i]) if(nxt != parent) res += dfs(nxt, i, depth + 1, hasApple, graph, count);

        return res;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build an adjacency list representation of the tree
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        graph.putIfAbsent(edge[0], new ArrayList<>());
        graph.putIfAbsent(edge[1], new ArrayList<>());
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Depth-First Search (DFS) to calculate the time taken to collect all apples
    return dfs(0, hasApple, graph, -1);
}

private int dfs(int node, boolean[] hasApple, Map<Integer, List<Integer>> graph, int parent) {
    int time = 0;

    // Recursively explore children nodes
    for (int child : graph.get(node)) {
        if (child != parent) {
            time += dfs(child, hasApple, graph, node);
        }
    }

    // Check if the current node or any of its children contains an apple
    if (node == 0 || hasApple[node] || time > 0) {
        return time + 2; // 2 represents the time taken to walk back to the parent
    }

    return 0; // No apples in this subtree
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) {
        return 0;
    }

    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    Deque<Post> queue = new ArrayDeque<>();
    queue.offer(new Post(0, 0, false, hasApple));

    int time = 0;
    while (!queue.isEmpty()) {
        Post node = queue.poll();
        int currentApple = node.apples;
        int currentWeight = node.weight;
        int parentWeight = node.parentWeight;

        parentWeight += currentApple;

        if (node.isParent) {
            time += (currentApples - (parentWeight == 0 ? 0 : 1)) * 2;
        }

        for (int child : graph.get(node.id)) {
            Post next = new Post(child, currentWeight + (hasApple[child] ? 1 : 0), true, hasApple);
            queue.offer(next);
        }
    }

    return time;
}

