public String sortString(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    Map<Character, Integer> charCount = new HashMap<>();
    for (char c : s.toCharArray()) {
        charCount.put(c, charCount.getOrDefault(c, 0) + 1);
    }

    PriorityQueue<Character> minHeap = new PriorityQueue<>((a, b) -> charCount.get(a) - charCount.get(b));
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> charCount.get(b) - charCount.get(a));

    for (char c : s.toCharArray()) {
        if (charCount.get(c) > 1) {
            minHeap.offer(c);
        } else {
            minHeap.offer(c);
            maxHeap.offer(c);
        }
    }

    StringBuilder result = new StringBuilder();
    boolean isAscending = true;

    while (!minHeap.isEmpty()) {
        if (isAscending) {
            while (!minHeap.isEmpty() && charCount.containsKey(minHeap.peek())) {
                result.append(minHeap.poll());
                charCount.put(minHeap.peek(), charCount.get(minHeap.peek()) - 1);
            }
        } else {
            while (!maxHeap.isEmpty() && charCount.containsKey(maxHeap.peek())) {
                result.append(maxHeap.poll());
                charCount.put(maxHeap.peek(), charCount.get(maxHeap.peek()) - 1);
            }
        }
        isAscending = !isAscending;
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    char[] charArray = s.toCharArray();
    Arrays.sort(charArray);

    while (charArray.length > 0) {
        do {
            result.append(charArray[0]);
            charArray = removeFirstOccurrence(charArray, charArray[0]);
            if (charArray.length == 0) {
                break;
            }
        } while (charArray.length > 0 && !s.contains(String.valueOf(charArray[0])));

        do {
            result.append(charArray[charArray.length - 1]);
            charArray = removeLastOccurrence(charArray, charArray[charArray.length - 1]);
            if (charArray.length == 0) {
                break;
            }
        } while (charArray.length > 0 && !s.contains(String.valueOf(charArray[charArray.length - 1])));
    }

    return result.toString();
}

private char[] removeFirstOccurrence(char[] arr, char c) {
    int index = -1;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] == c) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        return arr;
    }
    for (int j = index; j < arr.length - 1; j++) {
        arr[j] = arr[j + 1];
    }
    arr[arr.length - 1] = '\0';
    return arr;
}

private char[] removeLastOccurrence(char[] arr, char c) {
    for (int i = arr.length - 1; i >= 0; i--) {
        if (arr[i] == c) {
            for (int j = i; j < arr.length - 2; j++) {
                arr[j] = arr[j + 1];
            }
            arr[arr.length - 1] = '\0';
            return arr;
        }
    }
    return arr;
}

public String sortString(String s) {
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    // Add all characters to minHeap and maxHeap
    for (char c : s.toCharArray()) {
        minHeap.add(c);
        maxHeap.add(c);
    }

    StringBuilder result = new StringBuilder();
    int mod = s.length() % 2 == 0 ? 2 : 1; // Ensure we do the same number of operations for both minHeap and maxHeap

    for (int i = 0; i < mod; i++) {
        while (!minHeap.isEmpty()) {
            result.append(minHeap.poll());
            if (maxHeap.isEmpty()) break;
            result.append(maxHeap.poll());
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }

    StringBuilder result = new StringBuilder();
    char[] charArray = s.toCharArray();
    Arrays.sort(charArray);
    int totalSize = charArray.length;

    boolean done = false;
    while (!done) {
        // Pick the smallest character
        for (int i = 0; i < totalSize; i++) {
            if (charArray[i] != '*') {
                result.append(charArray[i]);
                charArray[i] = '*';
                break;
            }
        }

        // Check if all characters are picked
        if (Character.toString(charArray).indexOf('*') == -1) {
            done = true;
        } else {
            char[] sortedArray = new char[totalSize];
            int i = 0;
            for (int j = 0; j < totalSize && i < sortedArray.length; j++) {
                if (charArray[j] != '*') {
                    sortedArray[i++] = charArray[j];
                }
            }

            // Sort the picked Characters
            Arrays.sort(sortedArray);

            // Pick the largest character
            for (int j = sortedArray.length - 1; j >= 0 && i < totalSize; j--) {
                if (charArray[j] != '*') {
                    result.append(sortedArray[j]);
                    charArray[j] = '*';
                    break;
                }
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
        char[] chars = s.toCharArray();
        Arrays.sort(chars);

        int i = 0, j = chars.length - 1, k = j;
        StringBuilder result = new StringBuilder();

        while (i <= j) {
            if (i == j) {
                result.append(chars[i]);
                break;
            }
            result.append(chars[i++]);
            if (k > i) {
                result.append(chars[k--]);
            } else {
                break;
            }
        }

        return result.toString();
    }

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;

    float targetSum = Arrays.stream(nums).sum() / 2.0f;
    int sum1 = 0;

    for (int i = 0; i < nums.length; i++) {
        sum1 += nums[i];
        if (sum1 == targetSum) return true;
        for (int j = i + 1; j < nums.length; j++) {
            if (sum1 + nums[j] == targetSum) return true;
        }
        if (sum1 == targetSum / Math.sqrt(nums.length)) return true;
    }

    for (int i = 1; i < nums.length; i++) {
        sum1 += nums[i];
        if (sum1 == targetSum) return true;
        for (int j = i + 1; j < nums.length; j++) {
            if (sum1 + nums[j] == targetSum) return true;
        }
        if (sum1 == targetSum / Math.sqrt(Math.sqrt(nums.length))) return true;
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    // Validate input
    if (nums == null || nums.length <= 1) {
        throw new IllegalArgumentException("Input array must have at least 2 elements");
    }

    // Calculate the total sum of the array
    long totalSum = Arrays.stream(nums).sum();

    // Calculate the target sum for each array based on half of the total sum
    long targetSum = totalSum / 2;

    // Check if there exists a subarray with the sum equal to target sum
    return subsetSum(nums, targetSum) != -1;
}

private int subsetSum(int[] nums, long targetSum) {
    int n = nums.length;
    boolean[][] dp = new boolean[n + 1][targetSum + 1];

    // Initialize the dp array
    Arrays.fill(dp[0], true);
    for (int i = 1; i <= targetSum; i++) {
        dp[0][i] = false;
    }

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= targetSum; j++) {
            if (j < nums[i - 1]) {
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
            }
        }
    }

    return dp[n][targetSum] ? 1 : -1;
}

