public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;

    if (sum % n != 0) {
        return false;
    }

    int target = sum / n;

    HashMap<Integer, Integer> countMap = new HashMap<>();
    countMap.put(0, 1); // Initialize with a base case for sum 0

    for (int i = 1; i <= n; i++) {
        int curSum = nums[i - 1];
        countMap.put(curSum, countMap.getOrDefault(curSum, 0) + 1);

        int complement = target - curSum;

        if (complement >= 0 && countMap.containsKey(complement)) {
            return true;
        }
    }

    return false;
}

