}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Cost array must not be null or empty");
    }

    if (cost.length == 1) {
        return cost[0];
    }

    int prev = cost[0], curr = cost[1], temp;

    for (int i = 2; i < cost.length; i++) {
        temp = curr;
        curr = Math.min(prev + cost[i], curr + cost[i - 1]);
        prev = temp;
    }

    return Math.min(prev, curr);
}

public int minCostClimbingStairs(int[] cost) {
    // Base case: if there are less than 2 steps, the minimum cost is 0
    if (cost.length < 2) {
        return 0;
    }

    // Initialize the minimum costs for the first two steps
    int minCost1 = cost[0], minCost2 = cost[1];

    // Iterate through the steps starting from the third step
    for (int i = 2; i < cost.length; i++) {
        // Calculate the minimum cost to reach the current step
        int current = cost[i] + Math.min(minCost1, minCost2);

        // Update the minimum costs for the previous two steps
        minCost1 = minCost2;
        minCost2 = current;
    }

    // The minimum cost to reach the top is the minimum of the last two steps
    return Math.min(minCost1, minCost2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 1)
        return n == 0 ? 0 : cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);

    for (int i = 2; i < n; ++i) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null ||(cost.length < 2)) {
        throw new IllegalArgumentException("Cost array must contain at least two elements");
    }

    int[] dp = new int[cost.length + 1];
    dp[0] = dp[1] = 0;

    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[cost.length];
}

public int minCostClimbingStairs(int[] cost) {
    // Check if the cost array is empty or has only one element
    if (cost == null || cost.length <= 1) {
        return 0;
    }

    // Initialize the dp array
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);

    // Fill the dp array
    for (int i = 2; i < cost.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    // The minimum cost to reach the top of the floor is the last element in the dp array
    return dp[dp.length - 1];
}

