public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) return false;

    int needed = (int) Math.pow(2, k);
    boolean[] seen = new boolean[needed];

    int right = 0;
    while (right < s.length()) {
        int substringStart = right - k + 1;
        if (substringStart >= 0 && !seen[s.substring(substringStart, right + 1).hashCode()]) {
            seen[s.substring(substringStart, right + 1).hashCode()] = true;
        } else {
            return false;
        }
        right++;
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }

    HashSet<String> substrings = new HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        substrings.add(substring);
    }

    return substrings.size() == 1 << k;
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < k) return false;
    Set<String> window = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String binaryString = s.substring(i, i + k);
        if (!window.add(binaryString)) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k || k <= 0) {
        return false;
    }

    boolean[] binaryCodes = new boolean[1 << k];  // Generate all binary codes of length k
    for (int i = 0; i < 1 << k; i++) {
        binaryCodes[i] = isSubString(s, k, i);  // Check if each binary code is a substring of s
    }

    return Arrays.stream(binaryCodes).allMatch(b -> b);  // Check if all binary codes are true
}

private boolean isSubString(String s, int k, int code) {
    int temp = code << (s.length() - k);
    return s.substring(0, k).equals(Long.toBinaryString(temp));
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || k >= s.length()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    Set<String> existCodes = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String code = s.substring(i, i + k);
        if (code == null || code.length() != k) {
            throw new IllegalArgumentException("Invalid substring");
        }
        existCodes.add(code);
        if (k == existCodes.size()) {
            return true;
        }
    }
    return false;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    if（sentence == null || searchWord == null） {
        throw new IllegalArgumentException("Input strings cannot be null");
    }

    int wordIndex = 0;
    int paragraphIndex = 0;

    while（wordIndex < sentence.length()） {
        paragraphIndex = sentence.indexOf(' ', wordIndex);
        if（paragraphIndex == -1） {
            paragraphIndex = sentence.length();
        }

        String currentWord = sentence.substring(wordIndex, paragraphIndex);
        if（currentWord.startsWith(searchWord）） {
            return wordIndex;
        }

        wordIndex = paragraphIndex + 1;
    }

    return -1;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    if (searchWord.isEmpty()) {
        return -1;
    }

    String[] words = sentence.split(" ");
    for (int i = 0; i < words.length; i++) {
        if (words[i].startsWith(searchWord)) {
            return i;
        }
    }

