public int minOperations(int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += 2 * i + 1; // Calculate the sum of the array
    }
    int target = sum / n; // Calculate the target as the average of the sum
    int diff = sum - n * target; // Calculate the difference between the sum and the target
    if (diff > 0) {
        // If the difference is positive, perform operations to balance the sum
        return (int) (diff * (2.0 * n / (n - 1)));
    } else {
        // If the difference is zero, all elements are already equal
        return n;
    }
}

