    Stack<Integer> stack = new Stack<>();
    int sum = 0;

    for (int i = fib.length - 1; i >= 0; i--) {
        if (k >= fib[i]) {
            sum += fib[i];
            stack.push(fib[i]);
            k -= fib[i];
        }
    }

    return stack.size();
}

