private int findFibonacci(int k) {
    int a = 0, b = 1;
    if (k <= 1) return k;

    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }

    return a - k;
}

public int findMinFibonacciNumbers(int k) {
