    fibonacciNumbers.add(1);
    fibonacciNumbers.add(1);
    while (true) {
        int nextFibonacci = fibonacciNumbers.get(fibonacciNumbers.size() - 1) + fibonacciNumbers.get(fibonacciNumbers.size() - 2);
        if (nextFibonacci > k) break;
        fibonacciNumbers.add(nextFibonacci);
    }
    int minFibonacciNumbers = 0;
    int remaining = k;
    while (remaining != 0) {
        for (int i = fibonacciNumbers.size() - 1; i >= 0; i--) {
            if (fibonacciNumbers.get(i) <= remaining) {
                minFibonacciNumbers++;
                remaining -= fibonacciNumbers.get(i);
                break;
            }
        }
    }
    return minFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
