        int b = 1;
        fibNumbers.add(a);
        fibNumbers.add(b);

        while (b <= k) {
            int nextFib = a + b;
            fibNumbers.add(nextFib);
            a = b;
            b = nextFib;
        }

        Collections.reverse(fibNumbers);
        int count = 0;

        for (int fib : fibNumbers) {
            while (k >= fib) {
                k -= fib;
                count++;
            }
        }

        return count;
    }

