public int maxUniqueSplit(String s) {
    // Helper function to check if a substring can be split into unique substrings
    boolean valid(String substring) {
        Set<Character> unique_chars = new HashSet<>();
        for (char c : substring.toCharArray()) {
            if (unique_chars.contains(c)) {
                return false;
            }
            unique_chars.add(c);
        }
        return true;
    }

    // Use a backtracking approach to find the maximum number of unique substrings
    return maxUniqueSplit(s, 0, new HashSet<>(), 0, 0);
}

private int maxUniqueSplit(String s, int index, Set<Character> unique_chars, int current_split_count, int max_split_count) {
    int n = s.length();
    if (index >= n) {
        return current_split_count;
    }

    for (int i = index; i < n; i++) {
        String substring = s.substring(index, i + 1);
        if (valid(substring)) {
            unique_chars.add(substring.charAt(0));
            int result = maxUniqueSplit(s, i + 1, unique_chars, current_split_count + 1, max_split_count);
            unique_chars.remove(substring.charAt(0));
            max_split_count = Math.max(max_split_count, result);
        }
    }

    return max_split_count;
}

boolean valid(String substring) {
        Set<Character> unique_chars = new HashSet<>();
        for (char c : substring.toCharArray()) {
            if (unique_chars.contains(c)) {
                return false;
            }
            unique_chars.add(c);
