public int maxUniqueSplit(String s) {
        // Check if the input string is empty
        if (s == null || s.isEmpty()) {
            return 0;
        }

        int maxLength = 0;
        int[] counts = new int[26]; // Array to count occurrences of each character
        int start = 0; // Start index of the current splitting window

        for (int end = 0; end < s.length(); end++) {
            char currentChar = s.charAt(end);
            counts[currentChar - 'a']++;

            // If a character appears more than once
            if (counts[currentChar - 'a'] > 1) {
                // Split the string from the start to the last occurrence of the character and update maxLength
                maxLength = Math.max(maxLength, end - start);
                // Clear the start of the current substring
                while (counts[s.charAt(start) - 'a'] > 1) {
                    counts[s.charAt(start) - 'a']--;
                    start++;
                }
            }
        }

        // Handle the last segment if it contains unique characters
        maxLength = Math.max(maxLength, s.length() - start);

        return maxLength;
    }

public int maxUniqueSplit(String s) {
    int maxSubstrings = 0;
    Set<Character> currentSubstrings = new HashSet<>();

    for (int i = 0; i < s.length(); i++) {
        for (int j = i + 1; j <= s.length(); j++) {
            String currentSubstring = s.substring(i, j);
            if (!currentSubstrings.add(currentSubstring)) {
                // If the current substring already exists, backtrack and try the next possible suffix.
                break;
            } else {
                maxSubstrings++;
            }
        }
    }

    return maxSubstrings;
}

public int maxUniqueSplit(String s) {
       if (s == null || s.isEmpty()) return 0;

       int[] count = new int[26];
       int maxUnique = 0;
       int left = 0;

       for (int right = 0; right < s.length(); right++) {
           char c = s.charAt(right);
           count[c - 'a']++;

           while (count[c - 'a'] > 1) {
               count[s.charAt(left) - 'a']--;
               left++;
           }

           maxUnique = Math.max(maxUnique, right - left + 1);
       }

       return maxUnique;
   }

