public String getSmallestString(int n, int k) {
    StringBuilder sm = new StringBuilder();
    for (int str = n; str > 0; --str) {
        int offset = k % 26;
        k = k / 26;
        // When handling the first character, we need to take into account if its position is 1, add 1 and minus 26
        // If position is not 1, add offset then shift by 1
        if (str == n && offset == 0) {
            sm.append('z');
        } else {
            sm.append((char) ('a' + offset - (str == n && offset == 0 ? 1 : 26)));
        }
    }
    return sm.toString();
}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k must be positive integers");
    }

    StringBuilder result = new StringBuilder();

    while (k > 0) {
        int idx = k % 26; // calculate the character position
        char ch = (char) (97 + idx); // convert the index to a character
        result.append(ch); // append the character to the result
        k = (k / 26) + (k % 26 == 0 ? 1 : 0); // adjust the value for the next character
    }

    return result.reverse().toString(); // reverse the result to get the correct lexicographical order
}

public String getSmallestString(int n, int k) {
