        }
        n--;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    // Ensure n is reduced to不要太小，以减少后续计算的工作loads
    int reducedN = n;
    while (reducedN > 0 && k < 26 * reducedN) {
        reducedN--;
        k -= 26 * reducedN;
    }

    // Construct the result by appending 'a' characters
    char[] result = new char[reducedN];
    Arrays.fill(result, 'a');

    // Determine if we need to append any 'z' characters
    if (k > 0 && 26 * reducedN + k <= 26 * (reducedN + 1)) {
        result[reducedN - 1]--;
        int missingZones = k / 25; // Each 'z' takes 26 positions
        int extraZs = k % 25;
        Arrays.fill(result, reducedN - missingZones - 1, result.length, 'z');
        if (extraZs > 0) {
            result[result.length - 1] += extraZs;
        }
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0 || n * 26 < k) {
        throw new IllegalArgumentException("Invalid input");
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        // Calculate the smallest character needed to form the remainder
        result.append((char) ('a' + (k - 1) % 26));
        // Reduce the value by removing the case of the added character
        k -= (i == n - 1) ? 26 : (k - 1) % 26;
    }
    return result.toString();
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0; // Base case: The probability is always 1 when there's only one passenger or no passengers.
    }
    double[][] dp = new double[n][n]; // 2D DP array to store results for subproblems.
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j == i) {
                dp[i][j] = 1; // Probability of the last passenger sitting in their own seat.
            } else {
                dp[i][j] = 0; // Probability of the last passenger not sitting in their own seat.
            }
        }
    }
    for (int len = 3; len <= n; len++) {
        for (int i = 0; i <= n - len; i++) {
            int j = i + len - 1;
            for (int k = i; k < j; k++) {
                dp[i][j] += dp[i][k] * dp[k + 1][j];
            }
        }
    }
    return dp[0][n - 1] / (double)(n - 1); // Calculate the probability and return it as a double.
}

