public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0; // If there are 0 or 1 passengers, the last passenger will always sit in their own seat.
    } else if (n == 2) {
        return 0.5; // If there are 2 passengers, the probability is 1/2.
    } else {
        // for n > 2, we can use a dynamic programming approach to calculate the number of ways to seat the passengers
        // such that there are no collisions between the passengers and the positions they are sitting in.
        int[][] dp = new int[n][2];
        dp[0][0] = 1; // There is 1 way to seat 1 passenger in their own seat (the last passenger).
        dp[0][1] = 0; // There is 0 way to seat 1 passenger in someone else's seat (the last passenger cannot sit in their own seat).
        dp[1][0] = 1; // There is 1 way to seat 2 passengers in their own seats (the last passenger can sit in either position).
        dp[1][1] = 1; // There is 1 way to seat 2 passengers in someone else's seats (the last passenger can sit in either position).

        for (int i = 2; i < n; i++) {
            dp[i][0] = dp[i-1][0] + dp[i-1][1]; // The last passenger can either sit in their own seat or in someone else's seat.
            dp[i][1] = dp[i-1][0]; // The last passenger cannot sit in their own seat if the previous passenger is sitting in their own seat.
        }

        // The total number of ways to seat the passengers is the sum of the number of valid ways
        // to seat the passengers when there are no collisions.
        int totalWays = dp[n-1][0] + dp[n-1][1];

        // Calculate the probability that the last passenger will sit in their own seat.
        double probability = (double) dp[n-1][0] / totalWays;

        return probability;
    }
}

