public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int first = 0, second = 0, third = 0, fourth = 0;

    for (int num : nums) {
        if ((num & first) == 0) { // bit not set in first
            first |= num;
        } else { // bit set in first
            if ((num & second) == 0) { // bit not set in second
                second |= num;
            } else { // bit set in second and first, both set in third; update third
                third ^= num;
                first &= ~second;
            }
        }

        // reset first and second
        if ((num & third) != 0) { // bit set in third
            if ((num & second) == 0) { // bit not set in second
                first ^= num;
            } else { // bit set in second and first, both set in fourth; update fourth
                fourth ^= num;
                second &= ~third;
            }
        }

        // reset third
        if ((num & fourth) != 0) { // bit set in fourth
            twice = num;
        }
    }

    return first == twice ? second : first;
}

