public static boolean isPowerOfTwo(int n) {
    // Check for edge cases
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    // If n is only 1, it is an even power of 2 (0^0 = 1)
    if (n == 1) {
        return true;
    }

    // If n is even and > 1, it is not a power of 2
    while (n % 2 == 0) {
        if (n == 1) {
            return true;
        }
        n /= 2;
    }

    // If n is odd and greater than 1, it is not a power of 2
    return n == 1;
}

