public static int squarePermutations(int[] A) {
    int n = A.length;
    int count = 0;

    for (int i = 0; i < n - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (isPerfectSquare(sum)) {
            count += squarePermutationsDerivative(A, i, new HashSet<>());
        }
    }

    return count;
}

private static boolean isPerfectSquare(int x) {
    if (x < 0) return false;
    int s = (int) Math.sqrt(x);
    return s * s == x;
}

private static int squarePermutationsDerivative(int[] A, int start, Set<Integer> used) {
    int n = A.length;
    if (start >= n - 1) {
        return 1;
    }

    int count = 0;
    for (int i = start + 1; i < n; i++) {
        if (!used.contains(A[i])) {
            used.add(A[i]);
            count += squarePermutationsDerivative(A, i, used);
            used.remove(A[i]);
        }
    }

    return count;
}

public static int squarePermutations(int[] A) {
    // Initialize variables
    int n = A.length;
    int count = 0;
    // Use a hashmap to store the number of occurrences of each element
    HashMap<Integer, Integer> frequencies = new HashMap<>();
    // Count the occurrences of each element
    for (int num : A) {
        frequencies.put(num, frequencies.getOrDefault(num, 0) + 1);
    }
    // Calculate the number of square permutations
    for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
        int num = entry.getKey();
        int freq = entry.getValue();
        // If frequency is even, it can form pairs
        if (freq % 2 == 0) {
            count *= freq / 2;
        } else {
            // If frequency is odd, it must be paired with one
            // and the remaining odd number can be fixed at one end
            count /= 2;
            // Check if it can be handled with pair of same numbers
            if ((freq - 1) % 2 == 0) {
                count *= (freq - 1) / 2;
            } else {
                count = 0;
                break;
            }
        }
    }
    // Return the final result
    return count;
}

