public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0 || A.length % 2 != 0) {
            throw new IllegalArgumentException("Input array must be non-empty and even.");
        }

        int distinctValues = new HashSet<>(Arrays.asList(A)).size();
        if (distinctValues != A.length) {
            throw new IllegalArgumentException("Array contains duplicates, which is not allowed.");
        }

        int[] indices = new int[A.length];
        for (int i = 0; i < A.length; i++) {
            indices[i] = i;
        }

        int answer = 1;
        for (int i = 0; i < A.length - 1; i += 2) {
            answer *= helper(indices, i);
        }

        return answer;
    }

private static int helper(int[] A, int index) {
        int count = 0;
        for (int j = index + 2; j < A.length; j += 2) {
            if (A[index] + A[j] % 2 == 0 && isPerfectSquare(A[index] + A[j])) {
                swap(A, index, j);
                count += helper(A, index + 4);
                swap(A, index, j); // backtrack
            }
        }
        return count;
    }

private static boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

private static void swap(int[] A, int i, int j) {
        int temp = A[i];
        A[i] = A[j];
        A[j] = temp;
    }

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n <= 1) {
        return A.length == 1 ? 1 : 0;
    }

    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (Math.sqrt(A[i]) * Math.sqrt(A[i]) == A[j]) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = dp[i][i] * dp[j][j];
            }
        }
    }

    return dp[0][n - 1];
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    if (n == 0) {
        return 0;
    }

    int[] stack = new int[n];
    int top = -1;
    int maxArea = 0;

    for (int i = 0; i < n; i++) {
        while (top != -1 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top]];
            stack[top--];
            int width = top == -1 ? i : i - stack[top - 1] - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top]];
        stack[top--];
        int width = top == -1 ? n : n - stack[top - 1] - 1;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;

    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? 0 : heights[i];

        while (!stack.isEmpty() && heights[stack.peek()] >= currentHeight) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        stack.push(i);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int totalArea = 0;
    int currentMax = 0;
    int[] nextLargerLeft = get_new_array(heights.length);
    int[] nextLargerRight = get_new_array(heights.length);

    calc_next_larger_left(nextLargerLeft, heights); // store next smallest from each bar to the right
    calc_next_larger_right(nextLargerRight, heights); // store next smallest from each bar to the left

    for (int i = 0; i < heights.length; i++) {
        int height = heights[i];
        int nextRight = nextLargerRight[i];
        int nextLeft = nextLargerLeft[i];
        int width = nextRight - nextLeft - 1;
        int area = height * width;

        if (area > currentMax) {
            currentMax = area;
        }
        totalArea += currentMax;
    }
    return totalArea;
}

private static int[] get_new_array(int length) {
    int[] array = new int[length];
    return array;
}

private static void calc_next_larger_left(int[] nextLargerLeft, int[] heights) {
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (!stack.isEmpty()) {
            nextLargerLeft[i] = stack.peek();
        } else {
            nextLargerLeft[i] = -1;
        }
        stack.push(i);
    }
}

private static void calc_next_larger_right(int[] nextLargerRight, int[] heights) {
    Stack<Integer> stack = new Stack<>();
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (!stack.isEmpty()) {
            nextLargerRight[i] = stack.peek();
        } else {
            nextLargerRight[i] = heights.length;
        }
        stack.push(i);
    }
}

public static int largestRectangleArea(int[] heights) {
