    int[] right = new int[n];
    int maxArea = 0;

    // Build the left array
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j];
        }
        left[i] = j;
    }

    // Build the right array
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    // Calculate the maximum area
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i] - 1) * heights[i]);
    }

    return maxArea;
}

