        int y = Math.max(0, d + 1 - cols);
        while (x < rows && y < cols) {
            result.add(mat[x][y]);
            x++;
            y++;
        }
    }

    return result.stream().mapToInt(i -> i).toArray();
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int diagonalCount = rows + cols - 2;
    int row = 0;
    int col = 0;
    int index = 0;

    for (int diagonalIdx = 0; diagonalIdx <= diagonalCount; diagonalIdx++) {
        if (diagonalIdx % 2 == 0) {
            // Move left to right
            while (col < cols && row >= 0) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
            if (col >= cols) {
                row++;
            }
            if (row >= rows) {
                break;
            }
        } else {
            // Move right to left
            while (row < rows && col >= 0) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
            if (row >= rows) {
                break;
            }
            if (col < 0) {
                col++;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
