            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
        String numStr = String.valueOf(n);
        int[] digits = new int[numStr.length()];
        for (int i = 0; i < numStr.length(); i++) {
            digits[i] = numStr.charAt(i) - '0';
        }

        Arrays.sort(digits);
        // Find the index of the smallest digit that is greater than the first digit
        for (int i =(digits.length - 1); i > 0; i--) {
            if (digits[i - 1] < digits[i]) {
                // Swap the smallest digit and the first digit
                int temp = digits[i - 1];
                digits[i - 1] = digits[i];
                digits[i] = temp;
                // Sort the rest of the digits in ascending order
                Arrays.sort(digits, i);
                break;
            }
        }

        // Convert the sorted digits back to an integer
        StringBuilder smallestStr = new StringBuilder();
        for (int digit : digits) {
            smallestStr.append(digit);
        }
        int smallestInteger = smallestStr.length() > 0 ? Integer.parseInt(smallestStr.toString()) : -1;

        return smallestInteger;
    }

public static int findSmallestInteger(int n) {
    if (n <= 1) {
        return -1; // No smaller positive integers exist
    }

    String nums = n + ""; // Convert the input number to a string
    int length = nums.length();
    Integer[] array = new Integer[length];

    // Convert each character in the string to an integer and store them in the array
    for (int i = 0; i < length; i++) {
        array[i] = nums.charAt(i) - '0';
    }

    // Sort the array in descending order
    Arrays.sort(array);
    int prev = array[length - 1]; // Keep track of the last digit sorted

    // Find the index where to place the smallest digit greater than prev
    for (int i = length - 1; i >= 0; i--) {
        if (array[i] > prev) {
            // Perform the swap
            int j = i + 1;
            while (j < length && array[j] == prev) j++;
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
            // Rest of the array after i can be sorted in ascending order
            Arrays.sort(array, i + 1, length);
            // Convert the array back to a string and return
            return Integer.parseInt(String.join("", array));
        }
    }

    // If no such permutation exists, return -1
    return -1;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a character array to manipulate its digits
    char[] digits = Integer.toString(n).toCharArray();

    // Find the largest digit that is smaller than the next digit
    // This is needed to find the smallest rearranged integer
    int largestSmaller = -1;
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            largestSmaller = i;
            break;
        }
    }

    // If no such digit is found, return -1 as no rearrangement can be done
    if (largestSmaller == -1) {
        return -1;
    }

    // Swap the found largest smaller digit with the next digit
    for (int j = digits.length - 1; j >= 0; j--) {
        if (digits[j] > digits[largestSmaller]) {
            char temp = digits[largestSmaller];
            digits[largestSmaller] = digits[j];
            digits[j] = temp;
            break;
        }
    }

    // Sort the digits after the largest smaller digit to get the smallest possible number greater than n
    Arrays.sort(digits, largestSmaller + 1, digits.length);

    // Convert the character array back to an integer
    int smallestReversed = Integer.parseInt(new String(digits));

    // Return the smallest rearranged integer greater than n
    return smallestReversed;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] digits = new int[Integer.toString(n).length()];
    for (int i = 0; i < digits.length; i++) {
        digits[i] = n % 10;
        n /= 10;
    }

    int smallest = -1;
    for (int i = 0; i < digits.length; i++) {
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[i] > digits[j]) {
                // Swap digits[i] and digits[j]
                int temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;

                // Construct the new number
                int newNumber = 0;
                for (int k = 0; k < digits.length; k++) {
                    newNumber = newNumber * 10 + digits[k];
                }

                // Check if this new number is greater than the original and smaller than the smallest (if no smallest yet found)
                if (newNumber > n && (smallest == -1 || newNumber < smallest)) {
                    smallest = newNumber;
                }

                // Swap back to keep the array in its original order
                temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
            }
        }
    }

    return smallest;
}

public static int findSmallestInteger(int n) {
    // Convert the number to a character array
    char[] digits = Integer.toString(n).toCharArray();

    // Find the position to insert the smallest digit to compare with others
    int insertPosition = -1;
    for (int i = digits.length - 1; i > 0; i--) {
        if (Integer.parseInt(String.valueOf(digits[i])) < Integer.parseInt(String.valueOf(digits[i - 1]))) {
            insertPosition = i;
            break;
        }
    }

    // If no position is found, return -1
    if (insertPosition == -1) {
        return -1;
    }

    // Sort the remaining digits to find the smallest permutation
    Arrays.sort(digits, insertPosition + 1, digits.length, Comparator.comparingInt(c -> Integer.parseInt(String.valueOf(c))));

    // Convert the sorted character array back to an integer
    int smallestInteger = Integer.parseInt(new String(digits));

    // Return the smallest integer
    return smallestInteger;
}

