                } else if (sb.length() < n) {
                    sb = new StringBuilder(sb.substring(0, sb.length() / 2));
                    sb.reverse();
                    result.add(sb.toString() + possibleNumber + sb);
                }
            }
        }

        return result;
    }

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Input points array must have exactly 3 elements.");
    }

    // Extracting the first point
    int x1 = points[0][0], y1 = points[0][1];
    // Extracting the second point
    int x2 = points[1][0], y2 = points[1][1];
    // Extracting the third point
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the determinant of the matrix formed by the three points
    int determinant = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // If the determinant is not zero, the points form a triangle
    // If the determinant is zero, the points are coplanar and cannot form a boomerang
    return determinant != 0;
}

