public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3] {
        throw new IllegalArgumentException("Points array must have exactly three elements.");
    }

    int x1, y1, x2, y2, x3, y3;
    x1 = points[0][0];
    y1 = points[0][1];
    x2 = points[1][0];
    y2 = points[1][1];
    x3 = points[2][0];
    y3 = points[2][1];

    // Check if the points form a right angle
    if (Math.abs(y1 - y2) != Math.abs(x1 - x2)) {
        throw new IllegalArgumentException("All points must be on the same line.");
    }

    // Calculate the vectors forming the boomerang
    double v1x = x2 - x1;
    double v1y = y2 - y1;
    double v2x = x3 - x2;
    double v2y = y3 - y2;

    // Calculate the dot product of the two vectors
    double dotProduct = v1x * v2x + v1y * v2y;

    // Check if the dot product is not zero (i.e., the points are not collinear)
    return dotProduct != 0;
}

public static boolean isBoomerang(int[][] points) {
    // Check for an invalid input (less than 3 points)
    if (points.length < 3) {
        throw new IllegalArgumentException("The points array must contain at least 3 points.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the slopes of the lines formed by the points
    double slope1 = (y2 - y1) / (x2 - x1);
    double slope2 = (y3 - y2) / (x3 - x2);

    // Check if the slopes are not the same, indicating a boomerang
    return slope1 != slope2;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int nextUglyIndex = 1;
    int[] factors = {2, 3, 5};

    for (int i = 1; i < n; i++) {
        int next = Math.min(uglyNumbers[factors[0]] * 2, Math.min(uglyNumbers[factors[1]] * 3, uglyNumbers[factors[2]] * 5));
        if (next == uglyNumbers[nextUglyIndex - 1]) {
            factors[nextUglyIndex % 3]++;
        }
        uglyNumbers[i] = next;
        nextUglyIndex++;
    }

    return uglyNumbers[n - 1];
}

