        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int maxEnergy = 0;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
            maxEnergy = Math.max(maxEnergy, currentEnergy);
        } else {
            currentEnergy = 1;
        }
    }

    return maxEnergy;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0; // Edge case: empty string or null string
    }
    int maxEnergy = 0;
    int currentEnergy = 1;
    char prevChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == prevChar) {
            currentEnergy++; // Increment count if same character found
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy); // Update max energy
            currentEnergy = 1; // Reset count for new character
        }
        prevChar = s.charAt(i); // Update previous character
    }
    maxEnergy = Math.max(maxEnergy, currentEnergy); // Check for the last substring

    return maxEnergy;
}

