    List<List<Integer>> three = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        three.add(List.of(i));
    }

    // Build the rest of the numbers
    for (int placed = 0; placed < 3; placed++) {
        int lastValue = setNext(inputNumber, placed);
        if (lastValue <= n) {
