private void dfs(int i, int n, List<Integer> result) {
    // Base case: if i exceeds n, stop and return
    if (i > n) return;
    // Append current number i to the result
    result.add(i);
    // Explore deeper by multiplying i by 10
    if (i * 10 <= n) dfs(i * 10, n, result);
}

