}

private static void generate(int curr, int limit, List<Integer> ret) {
    if (curr > limit) {
        return;
    }
    ret.add(curr);
    for (int i = 0; i < 10; i++) {
        generate(curr * 10 + i, limit, ret);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    // Initialize the stack with all numbers less than n
    for (int i = 1; i <= Math.min(n, 9); i++) {
        result.add(i);
    }
    Integer cur = result.get(0);

    while (cur != null) {
        if ((cur * 10 <= n) && (cur * 10 > 0)) {
            // Push current * 10 onto stack
            result.add(cur * 10);
        }
        if (cur * 10 > n) {
            // Prune the current number
            result.remove(cur);
        }

        // Get the next number
        if ((cur / 10 == 0) || (cur / 10 > n)) {
            // Prune the current number
            result.remove(cur);
        } else {
            cur = cur / 10 * 10 + (cur / 10 % 10 + 1);
        }
    }

    return result;
}

