public static int minPerfectSquareSum(int n) {
    if (n <= 0) { // Invalid input: must be a positive integer
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int[] dp = new int[n + 1];

    // Initialize dp array with the maximum value
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }

    // Fill the dp array
    for (int i = 1; i * i <= n; i++) {
        for (int j = i * i; j <= n; j++) {
            dp[j] = Math.min(dp[j], 1 + dp[j - i * i]);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    if (n == 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int minSquares = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            minSquares = Math.min(minSquares, dp[i - j * j] + 1);
        }
        dp[i] = minSquares;
    }

    return dp[n];
}

