    }

    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Base case: If n is already a perfect square, return 1
    for (int i = 1; i <= n; i++) {
        int square = i * i;
        if (square == n) {
            return 1;
        }
    }

    // If n is not a perfect square, calculate the minimum number of perfect squares needed
    List<Integer> squares = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        squares.add(i * i);
    }

    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0; // Base case: 0 squares needed to sum up to 0
    dp[1] = 1; // Base case: 1 square (1^2) needed to sum up to 1

    for (int i = 2; i <= n; i++) {
        for (int j = 0; j < squares.size(); j++) {
            if (squares.get(j) <= i) {
                int sum = squares.get(j) + dp[i - squares.get(j)];
                if (sum < dp[i]) {
                    dp[i] = sum;
                }
            }
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ");

    for (int i = words.length - 1; i >= 0; i--) {
        if (i != words.length - 1) {
            result.append(" ");
        }
        result.append(new StringBuilder(words[i]).reverse().toString());
    }

    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        if (word != null && !word.isEmpty()) {
            char[] chars = word.toCharArray();
            for (int i = 0; i < chars.length / 2; i++) {
                char temp = chars[i];
                chars[i] = chars[chars.length - 1 - i];
                chars[chars.length - 1 - i] = temp;
            }
            result.append(String.valueOf(chars)).append(" ");
        }
    }

    return result.toString().trim();
}

public static String reverseWords(String s) {
    // Check if the input string is null or empty
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Split the string into words
    String[] words = s.split(" ");

    // Reverse the characters of each word and collect them into a new string
    StringBuilder reversedString = new StringBuilder();
    for (String word : words) {
        // Reverse the word
        String reversedWord = new StringBuilder(word).reverse().toString();
        // Append the reversed word to the result
        reversedString.append(reversedWord).append(" ");
    }

    // Remove the trailing space
    return reversedString.toString().trim();
}

public static String reverseWords(String s) {
    // Check if the input string is null or empty
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Split the input string into words
    String[] words = s.split(" ");

    // Iterate over each word and reverse its characters
    for (int i = 0; i < words.length; i++) {
        words[i] = new StringBuilder(words[i]).reverse().toString();
    }

    // Join the reversed words back into a single string
    return String.join(" ", words);
}

